"""Dump cardigan plans generated by the tree given as argv[1] to a JSON-lines file.

The tree root is forced onto sys.path and every loaded app module is asserted to
come from it (the repo .venv has an editable install of the main checkout).

Usage: python r3_dump_plans.py <tree root> <cardigan-open.json> <out.jsonl>
"""
import itertools
import json
import sys
from pathlib import Path

root = Path(sys.argv[1]).resolve()
sys.path.insert(0, str(root))

import app  # noqa: E402
import app.models.working_path as wp  # noqa: E402
from app.models.cardigan_design import CardiganRequest, assemble_cardigan  # noqa: E402

for module in (app, sys.modules["app.models.cardigan_design"], wp):
    assert Path(module.__file__).resolve().is_relative_to(root), module.__file__

base = json.loads(Path(sys.argv[2]).read_text())
with open(sys.argv[3], "w") as out:
    for body, sleeve, cuff in itertools.product(range(2, 42), (17, 18),
                                                ("open_review", "blo_to_reserved_flo")):
        raw = dict(base, body_length_cm=body * 10 / 28, sleeve_length_cm=sleeve * 10 / 28, cuff_seam=cuff)
        result = assemble_cardigan(CardiganRequest.model_validate(raw))
        inventory = None
        if result.plan is not None:
            # compiled by the checker of the same tree that generated the plan
            compiled = wp.compile_working_path(result.plan)
            stitches: dict[str, int] = {}
            for event in compiled.events:
                if event.role in ("working", "binding"):
                    stitches[event.stitch] = stitches.get(event.stitch, 0) + 1
            inventory = {"created": compiled.created_sites, "consumed": compiled.consumed_sites,
                         "final": {name: len(sites) for name, sites in compiled.final_edges.items()},
                         "steps": len(result.plan.steps), "stitches": stitches}
        out.write(json.dumps({"body": body, "sleeve": sleeve, "cuff": cuff, "stage": result.stage,
                              "inventory": inventory,
                              "plan": None if result.plan is None else result.plan.model_dump()}) + "\n")
print("wrote", sys.argv[3])
